steps.starterCode:
def ask(question):
    # try/except 包裹 invoke
    try:
        result = rag_chain.invoke({'input': question})
        if not result.get('context'):
            return '未检索到相关文档'
        return result['answer']
    except Exception as e:
        return f'查询出错: {e}'

print(ask('什么是Transformer?'))

